function mergeLabs(existing,incoming,mode,date){const out=copy(existing);for(const raw of incoming){if(!String(raw.value??'').trim())continue;const r=row({...normalizedLab(raw),date,confirmed:true});let matches=out.map((v,i)=>sameLab(v,r,date)?i:-1).filter(i=>i>=0);if(mode!=='append'&&!matches.length){matches=out.map((v,i)=>emptyLabMatch(v,r,date)?i:-1).filter(i=>i>=0);}if(mode==='append'||matches.length!==1){out.push(r);continue;}const i=matches[0];if(mode==='replace')out[i]={...r,id:out[i].id};else if(!String(out[i].value??'').trim())out[i]={...r,id:out[i].id};}return out;}
