function labGroup(r){if(['SBP','DBP','MAP'].includes(canonicalName(r.name,r.group))&&(!r.group||['혈압','기타 검사','기타 혈액검사','blood','additional'].includes(r.group)))return '혈압';if(labGroups.includes(r.group))return r.group;if(/요검사|urine|urinalysis/i.test(r.group))return '요검사';const n=canonicalName(r.name,r.group);if(templates.요검사.some(x=>x.toUpperCase()===n)||['요크레아티닌','요적혈구','요백혈구'].includes(n))return '요검사';if(['%NEU','%LYM','%MONO','%EOS','%BASO','%RETIC','MPV','PDW','PCT','P-LCR','TNCC','BAND'].includes(n))return 'CBC · 혈구검사';if(n==='BUN/CREA')return '신장 관련';if(n==='NA/K')return '전해질·무기질';if(/^(NT[- ]?PROBNP|PROBNP|CTNI|TROPONIN I)$/i.test(n))return '심장표지자';if(/^(TOTAL T4|FREE T4|T4|FT4|TSH)$/i.test(n)||/CORTISOL/.test(n))return '호르몬검사';if(/심장사상충|HEARTWORM|FELV|FIV/.test(n))return '감염성 검사';const idx=labMap.findIndex(a=>a.some(x=>x.toUpperCase()===n));return idx<0?(r.group==='blood'?'기타 혈액검사':'기타 검사'):labGroups[idx];}
