function splitClinicalText(value,labels){const result={note:[]};for(const line of String(value||'').split('\n')){const label=labels.find(x=>line.startsWith(x+': '));if(label&&!Object.hasOwn(result,label))result[label]=line.slice(label.length+2);else result.note.push(line);}result.note=result.note.join('\n').trim();return result;}
