function followupDate(base,offset){if(!/^\d{4}-\d{2}-\d{2}$/.test(base||''))return '';const date=new Date(base+'T12:00:00Z');if(!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==base)return '';if(offset==='month'){const day=date.getUTCDate();date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()+1);date.setUTCDate(Math.min(day,new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate()));}else date.setUTCDate(date.getUTCDate()+Number(offset));return date.toISOString().slice(0,10);}
function workflowState(chart,key){
 if(key==='summary'){
  if(chart.reviewed&&chart.clinicalStatus==='complete')return '검토 완료';
  if(chart.clinicalStatus==='amended')return '수정 후 확인 필요';
  const confirmed=managementConfirmed(chart).length,issues=(chart.managementIssues||[]).length;
  if(issues>confirmed)return '관리 항목 확인 필요';
  if(String(chart.summary||'').trim()||confirmed)return chart.reviewed?'검토 확인':'입력 완료';
  return ['overview','management','followup'].some(k=>String(chart[k]||'').trim())?'입력 중':'미입력';
 }

 let values=[],expected=0;if(['labs','urine','additional'].includes(key)&&!chart.labs.some(r=>labTab(r)===key))return '미구성';if(imageStep(key)&&!(chart.examSelection||[]).includes(key)&&!chart.exams[key]&&!chart.images.some(im=>im.kind===key))return '미구성';
 if(key==='exams'){const keys=[...new Set([...(chart.examSelection||[]),...Object.keys(chart.exams||{}).filter(k=>chart.exams[k])])].filter(k=>!imageStep(k));values=keys.map(k=>k==='nutrition'?[chart.bcs,chart.mcs,chart.exams[k]].filter(Boolean).join(' '):chart.exams[k]||'');expected=keys.length;}
 else if(['labs','urine','additional'].includes(key)){const rows=chart.labs.filter(r=>labTab(r)===key),entered=rows.filter(r=>String(r.value??'').trim()&&!waiting(r.value)&&r.value!=='미검사').length,pending=rows.filter(r=>waiting(r.value)).length,review=rows.filter(needsReview).length,unperformed=rows.filter(r=>r.value==='미검사').length;return [entered?'결과 '+entered+'개':'',review?'대조 필요 '+review+'개':'',pending?'대기 '+pending+'개':'',unperformed?'미검사 '+unperformed+'개':''].filter(Boolean).join(' · ')||'결과 미입력';}
 else if(imageStep(key)){values=[chart.exams[key]||''];expected=1;}
 else if(key==='summary'){values=[chart.overview,chart.summary,chart.management,chart.followup];expected=values.length;}
 if(values.some(waiting))return '결과 대기';
 const filled=values.filter(v=>String(v||'').trim());if(!filled.length)return imageStep(key)&&chart.images.some(im=>im.kind===key)?'소견 미입력':'미입력';
 if(filled.every(v=>v==='미검사'))return '미검사';
 if(filled.length<expected)return '입력 중';
 if(['labs','urine','additional'].includes(key)&&chart.labs.some(r=>labTab(r)===key&&needsReview(r)))return '원본 대조 필요';if(chart.reviewed)return '검토 완료';return '입력 완료';
}


// Management categories are explicitly confirmed by a clinician, never inferred from a reference interval.
const managementStates={priority:'우선 진료 필요',followup:'재검·추적관찰',care:'생활 관리',clear:'현재 특이 소견 없음',unperformed:'미검사',waiting:'결과 대기',deferred:'판정 보류'};
function managementBasis(d){
 const text=JSON.stringify([d.date,d.weight??'',String(d.history||'').trim(),String(d.medications||'').trim(),d.bcs||'',d.mcs||'',Object.entries(d.exams||{}).map(([k,v])=>[k,String(v||'').trim()]).sort(),(d.labs||[]).map(r=>['id','name','group','value','unit','reference','source','confirmed'].map(k=>typeof r[k]==='boolean'?r[k]:String(r[k]??'').trim())).sort(),(d.images||[]).map(r=>[r.id,r.kind,String(r.caption||'').trim(),r.includeInPrint!==false]).sort(),...['summary','management','followup'].map(k=>String(d[k]||'').trim())]);
 let hash=2166136261;for(let i=0;i<text.length;i++)hash=Math.imul(hash^text.charCodeAt(i),16777619);return (hash>>>0).toString(16);
}
function managementConfirmed(d){const basis=managementBasis(d);return (d.managementIssues||[]).filter(x=>x.confirmed&&x.basis===basis&&x.title&&managementStates[x.status]).sort((a,b)=>Object.keys(managementStates).indexOf(a.status)-Object.keys(managementStates).indexOf(b.status));}
function managementBadge(x){return '<span class="management-badge management-'+x.status+'">'+esc(managementStates[x.status])+'</span>';}
function managementLinked(issues,link){return issues.filter(x=>(x.links||[]).includes(link)).map(x=>'<span class="management-evidence">'+managementBadge(x)+' <a class="management-reference" data-management-ref href="#management-issue-'+esc(x.id)+'" title="'+esc(x.title)+'">관리 계획 <span data-management-page>—</span>쪽</a></span>').join('');}
function managementBrief(value){const text=String(value||'').trim().replace(/\s+/g,' ');return text.length<=90?text:'상세 페이지에서 확인';}

function managementSectionText(s){return (s.title?'['+s.title+']\n':'')+s.lines.join('\n').trim();}
function managementRemaining(d,issues){const out={...d};for(const k of ['summary','management','followup']){const used=new Set(issues.map(x=>x['source'+k]).filter(Boolean));out[k]=reportSections(d[k]).filter(s=>!used.has(managementSectionText(s))).map(managementSectionText).join('\n\n');}return out;}
function managementCandidates(d){
 const existing=d.managementIssues||[],used=new Set(existing.flatMap(x=>[x.title,...(x.links||[])])),items=[],groups=['summary','management','followup'].map(k=>reportSections(d[k]));
 const make=(title,fields={})=>({id:uid(),title,status:'',finding:'',meaning:'',action:'',timing:'',tests:'',links:[],confirmed:false,basis:'',...fields});
 for(const s of groups[0])if(s.title&&!used.has(s.title)&&groups[0].filter(x=>x.title===s.title).length===1){const matching=groups.slice(1).map(g=>g.filter(x=>x.title===s.title)),m=matching[0].length===1?matching[0][0]:null,f=matching[1].length===1?matching[1][0]:null;items.push(make(s.title,{finding:s.lines.join('\n').trim(),action:m?.lines.join('\n').trim()||'',timing:f?.lines.join('\n').trim()||'',sourcesummary:managementSectionText(s),sourcemanagement:m?managementSectionText(m):'',sourcefollowup:f?managementSectionText(f):''}));used.add(s.title);}
 // Prefer the patient's written problem list; do not duplicate it with one card per abnormal analyte.
 if(!items.length&&!existing.length){
  for(const [k,v] of Object.entries(d.exams||{}))if(String(v||'').trim())items.push(make(exams[k]||k,{finding:v,links:['exam:'+k]}));
  const abnormal=(d.labs||[]).filter(r=>r.confirmed&&outsideRange(r));for(const group of groupedLabs(abnormal)){const rows=group.rows.map(x=>x.r);items.push(make(group.group,{finding:rows.map(r=>r.name+' '+r.value+' '+r.unit+' (참고범위 '+r.reference+')').join('\n'),links:rows.map(r=>'lab:'+r.id)}));}
 }
 return items.slice(0,30-existing.length);
}
function managementParts(d){
 const issues=managementConfirmed(d);if(!issues.length)return [];
 const table='<p class="management-intro">담당 수의사가 확인한 관리 계획입니다. 참고범위 이탈과 진료 우선순위는 서로 다를 수 있습니다.</p><div class="management-counts">'+Object.entries(managementStates).map(([k,l])=>{const n=issues.filter(x=>x.status===k).length;return n?'<span>'+managementBadge({status:k})+' <b>'+n+'</b></span>':'';}).join('')+'</div><table class="management-table"><thead><tr><th>관리 항목·상태</th><th>핵심 소견</th><th>실천할 일</th><th>재검·예정 검사</th><th>상세</th></tr></thead><tbody>'+issues.map(x=>'<tr><td><strong>'+esc(x.title)+'</strong>'+managementBadge(x)+'</td>'+[['finding',x.finding||'상세 소견 참조'],['action',x.action||'별도 안내'],['timing',[x.timing,x.tests].filter(Boolean).join(' · ')||'별도 안내']].map(([k,v])=>'<td data-management-summary="'+esc(x.id)+'|'+k+'" data-summary-label="'+esc(x.title)+' · '+({finding:'핵심 소견',action:'실천할 일',timing:'재검·예정 검사'}[k])+'" data-summary-original="'+esc(v)+'">'+esc(managementBrief(v))+'</td>').join('')+'<td><a class="management-page-link" href="#management-issue-'+esc(x.id)+'"><span data-management-page>—</span>쪽</a></td></tr>').join('')+'</tbody></table>';
 return [{title:'이번 검진 관리 요약',summary:true,body:table+'<p class="management-reading-note">긴 소견과 자세한 관리 방법은 오른쪽 상세 쪽수에서 확인해주세요.</p>'},...issues.map(x=>({title:'소견·계획 · '+x.title,summary:true,body:'<div id="management-issue-'+esc(x.id)+'" class="management-issue-heading">'+managementBadge(x)+'</div>'+[['확인한 소견',x.finding],['소견의 의미',x.meaning],['집에서 실천할 일',x.action],['재검 시점',x.timing],['예정 검사·진료',x.tests]].filter(([,v])=>v).map(([label,value])=>'<article class="management-detail"><h3>'+label+'</h3><p>'+esc(value)+'</p></article>').join('')}))];
}

function blank(){return {date:today(),time:'',patient:{sex:'unknown',neutered:'unknown'},weight:null,veterinarian:'',history:'',medications:'',clinicalStatus:'inProgress',bcs:null,mcs:'',examSelection:['physical','nutrition'],exams:{},labs:[],images:[],managementIssues:[],overview:'',comparisonRecordId:'',summary:'',management:'',followup:'',questions:'',aiSource:'',reviewed:false};}
function row(v={}){return {id:uid(),group:'',name:'',originalName:'',value:'',unit:'',reference:'',source:'',date:'',confirmed:false,...v};}
function rangeStatus(r){const val=String(r.value??'').trim(),ref=String(r.reference??'').trim();if(!val)return '';if(waiting(val))return '결과 대기';if(val==='미검사')return '미검사';if(!r.confirmed)return '대조 전';if(val==='판정 보류')return '판정 보류';if(/^(음성|양성|negative|positive|검출|불검출)$/i.test(val))return '정성 결과';const number='[-+]?(?:\\d+(?:\\.\\d+)?|\\.\\d+)';if(!new RegExp('^'+number+'$').test(val))return '수치 비교 불가';const n=Number(val),m=ref.match(new RegExp('^\\s*('+number+')\\s*(?:~|–|—|-)\\s*('+number+')\\s*$'));if(m&&+m[1]<=+m[2])return n<+m[1]?'낮음':n>+m[2]?'높음':'범위 내';const one=ref.match(new RegExp('^\\s*(<=|>=|<|>|≤|≥)\\s*('+number+')\\s*$'));if(one){const op=one[1],v=+one[2],ok=op==='<'?n<v:op==='>'?n>v:op==='≤'||op==='<='?n<=v:n>=v;return ok?'범위 내':op.includes('<')||op==='≤'?'높음':'낮음';}return ref?'참고범위 형식 확인':'참고범위 미제공';}
function outsideRange(r){return ['높음','낮음'].includes(rangeStatus(r));}
function updateLabState(card,r){card.querySelector('[data-range]').textContent=rangeStatus(r);card.classList.toggle('hc-lab-abnormal',outsideRange(r));}
function printLabs(labs,previous=null,issues=[]){
 const labels={WBC:'백혈구',RBC:'적혈구',HGB:'혈색소',HCT:'적혈구 용적률',PLT:'혈소판',BUN:'요소질소',CREA:'크레아티닌',SDMA:'SDMA',ALT:'ALT',AST:'AST',ALP:'ALP',TP:'총단백',ALB:'알부민',GLOB:'글로불린',GLU:'혈당',CHOL:'콜레스테롤',TG:'중성지방',CA:'칼슘',P:'인',NA:'나트륨',K:'칼륨',CL:'염소',USG:'요비중',UPC:'요단백/크레아티닌 비율'};
 const groups=groupedLabs(labs.filter(r=>String(r.value??'').trim())),sources=[...new Set(labs.map(r=>r.source).filter(Boolean))],commonSource=sources.length===1&&labs.every(r=>r.source===sources[0]);
 const header='<thead><tr><th>검사 항목</th><th class="numeric">이번 결과</th>'+(previous?'<th class="numeric">이전 결과<small>'+esc(previous.date)+'</small></th>':'')+'<th>단위</th><th>참고범위</th><th>참고범위 대비</th></tr></thead>';
 return (commonSource?'<p class="lab-source">검사기관 · '+esc(sources[0])+'</p>':'')+'<table class="lab-table '+(previous?'with-prior':'')+'">'+header+groups.map(g=>{
  return '<tbody><tr class="lab-group-row"><th colspan="'+(previous?6:5)+'" scope="colgroup">'+esc(g.group)+'</th></tr>'+g.rows.map(({r})=>{
   const c=previous?labComparison(r,previous,labs):null,label=labels[canonicalName(r.name,r.group)],state=rangeStatus(r);
   return '<tr class="lab-result"><td>'+esc(r.name)+managementLinked(issues,'lab:'+r.id)+(label&&label!==r.name?'<small class="lab-name"> '+esc(label)+'</small>':'')+(!commonSource&&r.source?'<small>'+esc(r.source)+'</small>':'')+'</td><td class="numeric '+(outsideRange(r)?'lab-abnormal':'')+'">'+esc(r.value)+(outsideRange(r)?' '+(state==='높음'?'↑':'↓'):'')+'</td>'+(c?'<td class="numeric">'+esc(c.value)+(c.unit&&c.unit!==r.unit?' '+esc(c.unit):'')+'<small class="comparison-note '+(c.comparable?'is-comparable':'')+'">'+esc(c.note)+'</small>'+(!c.comparable&&c.source?'<small class="comparison-note">'+esc(c.source)+' · '+esc(c.reference||'참고범위 미제공')+'</small>':'')+'</td>':'')+'<td>'+esc(r.unit)+'</td><td>'+esc(r.reference||'미제공')+'</td><td class="'+(outsideRange(r)?'lab-abnormal':'')+'">'+esc(state)+'</td></tr>';
  }).join('')+'</tbody>';
 }).join('')+'</table>';
}
