function mediaQueue(limit=4){
 let active=0;const queue=[];
 const pump=()=>{while(active<limit&&queue.length){const job=queue.shift();active++;Promise.resolve().then(job.run).then(job.resolve,job.reject).finally(()=>{active--;pump();});}};
 return run=>new Promise((resolve,reject)=>{queue.push({run,resolve,reject});pump();});
}
// The next action follows configured tests; every tab remains available for adding tests.
function nextWorkStep(chart,key){
 const relevant=k=>['exams','summary'].includes(k)||(['labs','urine','additional'].includes(k)?chart.labs.some(r=>labTab(r)===k):(chart.examSelection||[]).includes(k)||!!chart.exams[k]||chart.images.some(im=>im.kind===k));
 const unfinished=k=>['labs','urine','additional'].includes(k)?chart.labs.some(r=>labTab(r)===k&&(!String(r.value||'').trim()||needsReview(r)||waiting(r.value))):!['입력 완료','검토 완료','미검사'].includes(workflowState(chart,k));
 const later=steps.slice(steps.findIndex(([k])=>k===key)+1).map(([k])=>k).filter(relevant);
 return later.find(unfinished)||'summary';
}
