function proseDiff(current,next){
 const a=Array.from(String(current||'')),b=Array.from(String(next||''));let first=0,last=0;
 while(first<a.length&&first<b.length&&a[first]===b[first])first++;
 while(last<a.length-first&&last<b.length-first&&a[a.length-1-last]===b[b.length-1-last])last++;
 if(first===a.length&&first===b.length)return esc(next||'미입력');
 const middle=b.slice(first,last?b.length-last:undefined).join('');
 return esc(b.slice(0,first).join(''))+(middle?'<mark>'+esc(middle)+'</mark>':'<em>삭제 제안</em>')+esc(last?b.slice(-last).join(''):'');
}
