 const choose=(b,l,r,key,label)=>{if(same(l,r)||same(b,r))return clone(l);if(same(b,l))return clone(r);conflicts.push({key,label,local:clone(l),remote:clone(r)});return clone(choices[key]==='remote'?r:l);};
