 function confirmMove(){
  if(busy||moveDialog)return Promise.resolve(false);
  if(!dirty&&!fileQueue.length&&!proposal)return Promise.resolve(true);
  return new Promise(resolve=>{
   const n=epoch,dialog=document.createElement('dialog');moveDialog=dialog;dialog.className='hc-record hc-move-dialog';
   dialog.innerHTML='<h2>작성 중인 기록에서 이동</h2><p>입력한 내용을 저장한 뒤 이동할 수 있습니다.</p>'+(fileQueue.length?'<p>미반영 검사 파일 '+fileQueue.length+'개는 먼저 검토하거나 아래에서 제외 여부를 선택해주세요.</p><label class="hc-check"><input type=checkbox data-move-files>미반영 검사 파일은 제외하고 이동</label>':'')+(proposal?'<p>미반영 AI 제안은 이 창에서 보관됩니다. 같은 기록을 다시 열면 검토를 이어갈 수 있습니다. 새로고침·창 닫기 전에는 필요한 내용을 반영해주세요.</p>':'')+'<p data-move-status role=status></p><div class="hc-move-actions"><button type=button data-move=stay>계속 작성</button><button type=button data-move=discard>변경 버리고 이동</button><button type=button data-move=save class=pt-primary>저장 후 이동</button></div>';
   let settled=false;const finish=ok=>{if(settled)return;settled=true;closeMove();resolve(ok);if(!ok)scheduleAutosave();};
   dialog.addEventListener('cancel',e=>{e.preventDefault();if(!busy)finish(false);});dialog.addEventListener('close',()=>{if(!settled){settled=true;resolve(false);}});
   dialog.querySelector('[data-move=stay]').onclick=()=>finish(false);
   dialog.querySelector('[data-move=discard]').onclick=()=>{if(!live(n)||busy)return finish(false);cacheProposal();finish(true);};
   dialog.querySelector('[data-move=save]').onclick=async()=>{
    if(!live(n)||!edit()||busy)return;
    if(fileQueue.length&&!dialog.querySelector('[data-move-files]').checked){dialog.querySelector('[data-move-status]').textContent='미반영 파일을 먼저 검토하거나 제외에 체크해주세요.';return;}
    if(inputIssue()){const issue=inputIssue();finish(false);locateIssue(issue);status('저장 전 확인 · '+issue.label+'을 확인해주세요.');return;}
    dialog.querySelectorAll('button,input').forEach(el=>el.disabled=true);
    const ok=!dirty||await save();
    if(!live(n))return finish(false);
    if(!ok){finish(false);return;}
    cacheProposal();finish(true);
   };
   document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-move=stay]').focus();
  });
 }
