 function syncProse(){if(!proseDialog)return;const key=proseDialog.dataset.proseKey;proseDialog.querySelector('[data-prose-target]').hidden=!saveIssue;const limit=key==='followup'?followupBudget(d.followup).maxNote:proseLimit(key);proseDialog.querySelector('textarea').maxLength=limit;proseDialog.querySelector('[data-prose-dialog-count]').textContent=proseCountText(key);const input=proseDialog.querySelector('textarea'),button=proseDialog.querySelector('[data-prose-save]');input.readOnly=busy||!edit()||!!conflict||!!pending;button.disabled=busy||!edit()||!!conflict;proseDialog.querySelector('[data-prose-status]').textContent=busy?'저장 중…':conflict?'동시 수정 확인 필요 · 편집을 마치고 최신 기록과 비교해주세요.':error.startsWith('저장 실패')?error:saveIssue?error:dirty?'저장 전 변경 있음 · 입력 중단 15초 후 자동 저장':saveMark?'저장 완료 · '+saveMark:'저장된 기록';}
