  dialog.querySelector('[data-prose-target]').onclick=()=>{const issue=saveIssue;closeProse();locateIssue(issue);};dialog.querySelector('[data-prose-close]').onclick=()=>dialog.close();dialog.querySelector('[data-prose-save]').onclick=()=>void save();
  dialog.onclose=()=>{if(proseDialog===dialog)proseDialog=null;composing=false;dialog.remove();const current=root.querySelector('[data-prose="'+key+'"]');if(current){fitProse(current);current.focus({preventScroll:true});}scheduleAutosave();};
