 function attachContext(panel){const holder=panel.querySelector('.hc-history');if(!item.patient_id||!holder)return;const button=document.createElement('button');button.textContent='다른 기록의 과거력·약물 가져오기';button.type='button';holder.append(button);button.onclick=async()=>{if(busy||!edit())return;const n=epoch;button.disabled=true;try{const r=await request('/chronic-context?patientId='+encodeURIComponent(item.patient_id));if(!live(n)||!holder.isConnected)return;let box=holder.querySelector('[data-intake-context]');if(!box){box=document.createElement('div');box.dataset.intakeContext='';holder.append(box);}const values=(r.items||[]).filter(x=>x.id!==item.id&&x.medications),medText=x=>'['+x.date+' · '+(x.title||x.category)+']\n'+x.medications;box.innerHTML=values.length?values.map((x,i)=>'<label class="hc-check"><input type=checkbox data-context-med="'+i+'" '+(d.medications.includes(medText(x))?'disabled data-already-imported':'')+'>'+esc(x.date+' · '+(x.title||x.category))+'<span>'+esc(x.medications)+'</span>'+(d.medications.includes(medText(x))?'<small>이미 가져옴</small>':'')+'</label>').join('')+'<button data-context-apply>현재 사용 약물로 확인·가져오기</button>':'가져올 약물 기록이 없습니다. 이전 검사의 과거력은 아래에서 연결할 수 있습니다.';box.insertAdjacentHTML('beforeend','<button data-context-prior>이전 건강검진 과거력 보기</button><div data-intake-history></div>');box.querySelector('[data-context-apply]')?.addEventListener('click',()=>{const text=[...box.querySelectorAll('[data-context-med]:checked')].map(e=>{const x=values[+e.dataset.contextMed];return medText(x);}).filter(text=>!d.medications.includes(text)).join('\n');if(!text)return;d.medications=[d.medications,text].filter(Boolean).join('\n');changed();render();});box.querySelector('[data-context-prior]').onclick=async()=>{const target=box.querySelector('[data-intake-history]');try{const out=await request('/healthcheck?patientId='+encodeURIComponent(item.patient_id)+'&to='+d.date);if(!live(n)||!target.isConnected)return;target.innerHTML=(out.items||[]).filter(x=>x.id!==item.id).map(x=>'<button data-history-record="'+esc(x.id)+'">'+esc(x.date||x.updated_at||'이전 기록')+'</button>').join('')||'이전 건강검진 기록이 없습니다.';target.querySelectorAll('[data-history-record]').forEach(b=>b.onclick=async()=>{try{const out=await request('/cases/'+encodeURIComponent(b.dataset.historyRecord)+'?view=healthcheck');if(!live(n)||!target.isConnected)return;const chart=out.item.body.healthcheckChart;target.replaceChildren();const text=document.createElement('p');text.textContent=chart.date+' · '+(chart.history||'과거력 없음');target.append(text);if(chart.history){const apply=document.createElement('button');const importedHistory='[이전 검진 '+chart.date+']\n'+chart.history;apply.textContent=d.history.includes(importedHistory)?'이미 가져온 과거력':'확인한 과거력 가져오기';apply.disabled=d.history.includes(importedHistory);if(apply.disabled)apply.dataset.alreadyImported='';apply.onclick=()=>{if(d.history.includes(importedHistory))return;d.history=[d.history,importedHistory].filter(Boolean).join('\n');changed();render();};target.append(apply);}}catch(e){status(e.message);}});}catch(e){status(e.message);}};}catch(e){status('이전 기록 조회 실패 · '+e.message);}finally{if(live(n)&&button.isConnected)button.disabled=false;}};}
 function updateFollowupHint(){const hint=root.querySelector('[data-followup-hint]');if(!hint)return;const date=root.querySelector('[data-followup-date]')?.value;hint.textContent=date&&date<today()?'선택한 재검일 '+date+'은 오늘보다 이전입니다. 날짜를 확인해주세요.':'';hint.hidden=!hint.textContent;}
 function attachFollowupImport(section){
  const box=document.createElement('details');box.className='hc-followup-import';box.innerHTML='<summary>관리 항목에서 가져오기</summary><div data-followup-import-options></div>';section.querySelector('h3').after(box);
  box.ontoggle=()=>{if(!box.open)return;const target=box.querySelector('[data-followup-import-options]'),items=(d.managementIssues||[]).filter(x=>String(x.timing||'').trim()||String(x.tests||'').trim());
   target.innerHTML=items.length?'<p>가져올 일정을 선택하세요. 기존 날짜·메모는 유지하고, 항목별 일정은 추가 안내에 남깁니다.</p>'+items.map(x=>'<label class="hc-check"><input type=checkbox data-followup-import-pick="'+esc(x.id)+'"><span><strong>'+esc(x.title||'제목 없는 관리 항목')+'</strong><small>'+esc([x.timing,x.tests].filter(Boolean).join(' · '))+'</small></span></label>').join('')+'<button type=button data-followup-import-apply>선택한 재검 정보 가져오기</button><p data-followup-import-status role=status></p>':'<p>관리 항목에 재검 시점이나 예정 검사를 입력하면 여기에서 가져올 수 있습니다.</p>';
   target.querySelectorAll('[data-followup-import-pick]').forEach(e=>e.onchange=()=>buttons());
   const apply=target.querySelector('[data-followup-import-apply]');if(apply)apply.onclick=()=>{
    if(!edit()||busy||pending||conflict)return;
    const ids=new Set([...target.querySelectorAll('[data-followup-import-pick]:checked')].map(e=>e.dataset.followupImportPick)),chosen=(d.managementIssues||[]).filter(x=>ids.has(x.id)),parts=splitClinicalText(d.followup,['재검 날짜','예정 검사']);
    if(!chosen.length)return;
    let note=parts.note,added=0;for(const x of chosen){const block='['+(x.title||'관리 항목')+']\n'+[x.timing?'재검 시점: '+x.timing:'',x.tests?'예정 검사: '+x.tests:''].filter(Boolean).join('\n');if(!note.includes(block)){note=[note,block].filter(Boolean).join('\n\n');added++;}}
    const dates=[...new Set(chosen.map(x=>String(x.timing||'').trim()))],candidate=dates.length===1&&/^\d{4}-\d{2}-\d{2}$/.test(dates[0])&&Number.isFinite(Date.parse(dates[0]))&&new Date(dates[0]).toISOString().slice(0,10)===dates[0]?dates[0]:'';
    const date=parts['재검 날짜']||candidate,tests=[...new Set([parts['예정 검사']||'',...chosen.map(x=>x.tests||'')].flatMap(x=>x.split(',').map(y=>y.trim()).filter(Boolean)))].join(', '),next=joinClinicalText({'재검 날짜':date,'예정 검사':tests},note),message=target.querySelector('[data-followup-import-status]');
    if(next.length>8000){message.textContent='재검 안내가 8,000자를 넘습니다. 가져올 항목을 줄여주세요. 기존 입력은 유지했습니다.';return;}
    if(next===d.followup){message.textContent='선택한 재검 정보가 이미 반영되어 있습니다.';return;}
    section.querySelector('[data-followup-date]').value=date;section.querySelector('[data-followup-tests]').value=tests;editProse('followup',note);updateFollowupHint();
    target.querySelectorAll('[data-followup-import-pick]').forEach(e=>e.checked=false);buttons();message.textContent=added+'개 재검 정보를 가져왔습니다. '+(!candidate||parts['재검 날짜']&&parts['재검 날짜']!==candidate?'각 일정은 추가 안내에서 확인하세요. 기존 날짜는 유지했습니다.':'날짜·예정 검사·추가 안내를 확인해주세요.');
   };buttons();
  };
 }
 function attachFollowup(panel){
  const section=panel.querySelector('.hc-followup'),controls=document.createElement('div');controls.className='hc-followup-shortcuts';
  controls.innerHTML='<label>날짜 계산 기준<select data-followup-base><option value="record">검사일 '+esc(d.date)+'</option><option value="today">오늘 '+today()+'</option></select></label>'+[['7','1주'],['14','2주'],['month','1개월']].map(([k,v])=>'<button type=button data-followup-offset="'+k+'" data-offset-label="'+v+'"></button>').join('')+'<select data-followup-choice aria-label="예정 검사 추가"><option value="">예정 검사 추가</option>'+['혈액검사','요검사','혈압 측정','체중·BCS·MCS 확인','방사선 검사','초음파 검사','내복약 처방'].map(x=>'<option>'+x+'</option>').join('')+'</select>';
  section.querySelector('h3').after(controls);attachFollowupImport(section);const hint=document.createElement('p');hint.dataset.followupHint='';hint.setAttribute('role','status');controls.after(hint);
  const basis=controls.querySelector('[data-followup-base]');basis.value=followupBase;const labels=()=>controls.querySelectorAll('[data-followup-offset]').forEach(b=>b.textContent=(followupBase==='today'?'오늘':'검사일')+' + '+b.dataset.offsetLabel);labels();basis.onchange=()=>{followupBase=basis.value;labels();};
  controls.querySelectorAll('[data-followup-offset]').forEach(b=>b.onclick=()=>{const value=followupDate(followupBase==='today'?today():d.date,b.dataset.followupOffset);if(!value){status('날짜 계산 기준을 확인해주세요.');return;}const e=panel.querySelector('[data-followup-date]');e.value=value;e.dispatchEvent(new Event('input'));});
  controls.querySelector('[data-followup-choice]').onchange=e=>{if(!e.target.value)return;const input=panel.querySelector('[data-followup-tests]');input.value=[...new Set([...input.value.split(',').map(s=>s.trim()).filter(Boolean),e.target.value])].join(', ');input.dispatchEvent(new Event('input'));e.target.value='';};updateFollowupHint();
 }

 function renderExams(panel){const h=splitClinicalText(d.history,['검진 목적','주요 증상']);panel.innerHTML='<div class="hc-fields">'+field('date','검사일','date')+field('veterinarian','담당 수의사')+field('weight','체중 · kg','number')+'</div><details class="hc-history" '+(historyOpen?'open':'')+'><summary>문진·과거력·현재 약물</summary><div class="hc-fields hc-history-fields"><label>검진 목적<input list=hc-purposes data-history-purpose value="'+esc(h['검진 목적']||'')+'" placeholder="선택 또는 직접 입력"><datalist id=hc-purposes><option>정기 건강검진</option><option>노령 건강검진</option><option>증상 평가</option><option>재검·추적관찰</option><option>수술 전 평가</option></datalist></label><label>주요 증상<input data-history-symptoms value="'+esc(h['주요 증상']||'')+'" placeholder="보호자가 설명한 증상"></label><label>과거력·문진 메모<textarea data-field="history">'+esc(h.note)+'</textarea></label><label>현재 약물<textarea data-field="medications">'+esc(d.medications)+'</textarea></label></div></details><details class="hc-exam-selector"><summary>검사 추가·제외</summary><div class="hc-exam-picks">'+Object.entries(exams).filter(([k])=>!imageStep(k)).map(([k,l])=>'<label class="hc-check"><input type=checkbox data-exam-pick="'+k+'" '+(selectedExams().includes(k)?'checked':'')+'>'+l+'</label>').join('')+'</div></details><div data-exam-content>'+examContent()+'</div>';const updateHistory=()=>{d.history=joinClinicalText({'검진 목적':panel.querySelector('[data-history-purpose]').value,'주요 증상':panel.querySelector('[data-history-symptoms]').value},panel.querySelector('[data-field=history]').value);changed();};panel.querySelectorAll('[data-history-purpose],[data-history-symptoms],[data-field=history]').forEach(e=>e.oninput=updateHistory);attachWorkflow(panel,'healthcheck-template');attachStaff(panel);attachContext(panel);}
 function updateExamChips(key){
  const box=root.querySelector('[data-exam-selected="'+key+'"]');if(!box)return;
  const options=examOptions(key),lines=(d.exams[key]||'').split('\n'),selected=options.filter(v=>lines.some(x=>x.trim()===v));
  box.innerHTML=selected.map((value,i)=>'<button type=button data-remove-finding="'+i+'" aria-label="'+esc(value)+' 삭제">'+esc(value)+' <span aria-hidden=true>×</span></button>').join('');box.hidden=!selected.length;
  const select=root.querySelector('[data-exam-choice="'+key+'"]');select.value='';[...select.options].forEach(o=>o.disabled=selected.includes(o.value));
  box.querySelectorAll('[data-remove-finding]').forEach(b=>b.onclick=()=>{if(!edit()||busy||pending||conflict)return;const value=selected[+b.dataset.removeFinding];d.exams[key]=(d.exams[key]||'').split('\n').filter(x=>x.trim()!==value).join('\n');root.querySelector('[data-exam="'+key+'"]').value=d.exams[key];root.querySelector('[data-exam-preview="'+key+'"]').textContent=d.exams[key]||'입력 없음';changed();updateExamChips(key);buttons();select.focus({preventScroll:true});});
 }
 function bindExamFields(){
  root.querySelectorAll('[data-normal-pick]').forEach(e=>e.onchange=()=>buttons());
  const normal=root.querySelector('[data-normal-apply]');if(normal)normal.onclick=()=>{
   if(!edit()||busy||pending||conflict)return;let count=0;
   root.querySelectorAll('[data-normal-pick]:checked').forEach(e=>{const k=e.dataset.normalPick;e.checked=false;if(!selectedExams().includes(k)||!examChoices[k]||String(d.exams[k]||'').trim())return;d.exams[k]='특이 소견 없음';root.querySelector('[data-exam="'+k+'"]').value=d.exams[k];root.querySelector('[data-exam-preview="'+k+'"]').textContent=d.exams[k];updateExamChips(k);count++;});
   if(count)changed();buttons();status(count+'개 항목에 특이 소견 없음을 입력했습니다. 기존 소견은 유지했습니다.');
  };

  root.querySelectorAll('[data-exam-choice]').forEach(e=>{updateExamChips(e.dataset.examChoice);e.onchange=()=>{if(!e.value||!edit()||busy||pending||conflict)return;const k=e.dataset.examChoice,markers=['특이 소견 없음','미검사','결과 대기','평가 불가'],lines=(d.exams[k]||'').split('\n').filter(x=>x&&!markers.includes(x.trim()));if(markers.includes(e.value))for(let i=lines.length-1;i>=0;i--)if(examOptions(k).includes(lines[i].trim()))lines.splice(i,1);if(!lines.some(x=>x.trim()===e.value))lines.push(e.value);d.exams[k]=lines.join('\n');root.querySelector('[data-exam="'+k+'"]').value=d.exams[k];root.querySelector('[data-exam-preview="'+k+'"]').textContent=d.exams[k];changed();updateExamChips(k);buttons();};});
  root.querySelectorAll('[data-exam]').forEach(e=>e.oninput=()=>{d.exams[e.dataset.exam]=e.value;const preview=root.querySelector('[data-exam-preview="'+e.dataset.exam+'"]');if(preview)preview.textContent=e.value||'입력 없음';changed();updateExamChips(e.dataset.exam);buttons();});root.querySelectorAll('[data-context-photo]').forEach(b=>b.onclick=()=>{photoReturn=step;photoKind=b.dataset.contextPhoto;photoFilter=photoKind;goStep('images');});
 }
 function field(key,label,type='text'){return '<label>'+label+'<input data-field="'+key+'" type="'+type+'" value="'+esc(d[key])+'"></label>';}
 async function listOpen(more=false){if(busy)return;screen='list';const n=++epoch;status('불러오는 중…');try{const r=await request('/healthcheck?'+new URLSearchParams({q:query,...listFilters,...(more&&next?{cursor:next}:{})}));if(!live(n))return;list=more?list.concat(r.items||[]):r.items||[];next=r.next||'';error='';renderList();}catch(e){if(live(n)){renderList();readFailure(e,()=>listOpen(more));}}}
 function renderList(){root.className='hc-record';root.innerHTML='<div class="cs-record-list-actions"><button data-action="new" class="pt-primary">새 건강검진 기록</button><button data-action="refresh">새로고침</button></div><p class="hc-draft-help">저장된 초안은 ‘작성 중’에서, 저장 전 입력은 이 창에서 이어쓰세요.</p>'+((dirty||fileQueue.length||proposal)&&d?'<button data-action=resume>작성 중 기록 이어쓰기</button>':'')+'<form data-search class="hc-search"><label>검색<input name="q" value="'+esc(query)+'" placeholder="환자·보호자·차트번호"></label><label>기록 상태<select name=state><option value="">전체 상태</option>'+[['inProgress','작성 중'],['complete','검토 완료'],['amended','검토 후 수정']].map(([k,v])=>'<option value="'+k+'" '+(listFilters.status===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label><button>검색</button><details><summary>상세 조건</summary><label>시작일<input name=from type=date value="'+esc(listFilters.from)+'"></label><label>종료일<input name=to type=date value="'+esc(listFilters.to)+'"></label><label>담당 수의사<input name=vet value="'+esc(listFilters.vet)+'"></label></details></form><p data-hc-status role="status">'+esc(error)+'</p><div class="hc-list">'+list.map(r=>'<article class="hc-list-card"><button data-open="'+esc(r.id)+'"><b>'+esc(r.patient?.name||'환자')+'</b><span>'+esc(r.date)+' · '+esc(r.clinicalStatus==='complete'?'검토 완료':r.clinicalStatus==='amended'?'검토 후 수정':'작성 중')+'</span><small>'+esc([r.patient?.guardianName,r.patient?.chartNumber,r.veterinarian].filter(Boolean).join(' · '))+'</small></button>'+(edit()?'<button class="hc-delete" data-delete="'+esc(r.id)+'" aria-label="'+esc(r.patient?.name||'환자')+' 건강검진 기록 삭제">삭제</button>':'')+'</article>').join('')+'</div>'+(!list.length&&!error?'<p>건강검진 기록이 없습니다.</p>':'')+(next?'<button data-action="more">더 불러오기</button>':'');root.querySelector('[data-search]').onsubmit=e=>{e.preventDefault();query=e.target.q.value;listFilters={status:e.target.state.value,from:e.target.from.value,to:e.target.to.value,vet:e.target.vet.value};void listOpen();};root.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>void openRecord(b.dataset.open));root.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>void deleteRecord(b.dataset.delete));bind();root.querySelector('[data-action=new]').disabled=!edit();}
 async function deleteRecord(id){
  if(!id||!edit()||busy||pending||aiBusy)return;
  const shown=list.find(r=>r.id===id),name=(item?.id===id?item.patient?.name:shown?.patient?.name)||'선택한 환자';
  if(!g.confirm(name+'의 건강검진 기록을 삭제할까요?'))return;
  const n=epoch;busy=true;root.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true);status('삭제 중…');
  try{
   if(!deletePending||deletePending.id!==id){const r=item?.id===id?item:(await request('/cases/'+encodeURIComponent(id)+'?view=healthcheck')).item;if(!live(n))return;deletePending={id,body:{revision:r.revision,requestKey:uid(),kind:'case.delete',data:{confirm:true}}};}
   await request('/cases/'+encodeURIComponent(id)+'/events',{method:'POST',body:deletePending.body});if(!live(n))return;
   deletePending=null;proposalCache.delete(id);if(item?.id===id){clearProposal();reset();}busy=false;await listOpen();status('건강검진 기록을 삭제했습니다.');
  }catch(e){if(live(n)){if(e.status===400||e.status===403||e.status===409)deletePending=null;busy=false;screen==='record'?render():renderList();status('삭제 실패 · '+e.message);}}
  finally{if(live(n)){busy=false;buttons();}}
 }
