  const branding=copy(a.hospital?.()||{name:a.clinicName?.()||''});
  const n=epoch,chart=copy(d),patient={...item.patient,species:item.body.species},wanted=chart.images.filter(x=>x.includeInPrint!==false),loaded=new Map();
  let running=false,failed=[];let comparison=null;try{comparison=(await ensurePrior())?.chart||null;if((chart.comparisonRecordId||'')!==(d.comparisonRecordId||''))throw Error('비교 검사 선택이 변경됐습니다. 다시 출력해주세요.');}catch(e){win.close();status('비교 검사를 확인하지 못해 출력을 중단했습니다. '+e.message);return;}
