  const finish=omit=>{if(!valid()){if(!win.closed)win.close();return;}const images=wanted.filter(im=>loaded.has(im.id)).map(im=>({...im,dataUrl:loaded.get(im.id)}));let html=reportHTML(chart,patient,images,branding,{previous:comparison});if(omit&&failed.length)html=html.replace('</h1>','</h1><p class="draft">사진 '+failed.length+'장 불러오기 실패로 제외: '+failed.map(im=>esc((kinds[im.kind]||'사진')+' '+(wanted.findIndex(x=>x.id===im.id)+1)+(im.caption?' · '+im.caption:''))).join(', ')+'</p>');const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const cleanup=()=>URL.revokeObjectURL(url);win.addEventListener('load',()=>{if(win.location.href===url)cleanup();},{once:true});win.location.replace(url);setTimeout(cleanup,60000);};
  const load=async targets=>{if(running||!valid())return;running=true;const queue=[...targets],errors=[];failed=[];show();await Promise.all(Array.from({length:Math.min(3,queue.length)},async()=>{while(queue.length&&valid()){const im=queue.shift();try{const url=await imageURL(im);if(!url)throw Error('사진 없음');if(valid())loaded.set(im.id,url);}catch(e){errors.push(im);}if(valid())show();}}));running=false;failed=errors;if(!valid()){if(!win.closed)win.close();return;}if(failed.length)show();else finish(false);};
  await load(wanted);
